from typing import Dict, Any
from google.cloud import documentai_v1 as documentai
from google.api_core.client_options import ClientOptions

from document_models import InvoiceFields, LineItem

def extract_invoice_fields(file_content: bytes, mime_type: str) -> InvoiceFields:
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    location = os.getenv("GOOGLE_CLOUD_LOCATION") # e.g., us
    processor_id = os.getenv("DOCUMENT_AI_INVOICE_PROCESSOR_ID")

    if not all([project_id, location, processor_id]):
        raise ValueError("Missing Google Cloud Document AI environment variables for invoice extraction.")

    processor_name = f"projects/{project_id}/locations/{location}/processors/{processor_id}"

    # The Document AI regional endpoint must be consistent with the processor location.
    options = ClientOptions(api_endpoint=f"{location}-documentai.googleapis.com")
    client = documentai.DocumentProcessorServiceClient(client_options=options)

    raw_document = documentai.RawDocument(content=file_content, mime_type=mime_type)
    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)

    response = client.process_document(request=request)
    document = response.document

    vendor_name = ""
    invoice_date = ""
    total_amount = 0.0
    line_items = []

    for entity in document.entities:
        if entity.type == "vendor_name" and entity.mention_text:
            vendor_name = entity.mention_text
        elif entity.type == "invoice_date" and entity.mention_text:
            invoice_date = entity.mention_text # Keep as string for now, normalize later
        elif entity.type == "total_amount" and entity.mention_text:
            try:
                total_amount = float(entity.mention_text.replace('$', '').replace(',', ''))
            except ValueError:
                total_amount = 0.0
        elif entity.type == "line_item":
            description = ""
            amount = 0.0
            for prop in entity.properties:
                if prop.type == "description" and prop.mention_text:
                    description = prop.mention_text
                elif prop.type == "amount" and prop.mention_text:
                    try:
                        amount = float(prop.mention_text.replace('$', '').replace(',', ''))
                    except ValueError:
                        amount = 0.0
            if description or amount:
                line_items.append(LineItem(description=description, amount=amount))

    return InvoiceFields(
        vendor_name=vendor_name,
        invoice_date=invoice_date,
        total_amount=total_amount,
        line_items=line_items,
        raw_document_text=document.text
    )",
