from typing import Union

from document_models import InvoiceFields, ReceiptFields, NormalizedExpense, ExpenseSource, LineItem, ReceiptItem
from document_client import get_openai_client

def normalize_expense(extracted_data: Union[InvoiceFields, ReceiptFields]) -> NormalizedExpense:
    client = get_openai_client()

    source_type = ExpenseSource.UNKNOWN
    raw_extracted_text = ""
    prompt_data = {}

    if isinstance(extracted_data, InvoiceFields):
        source_type = ExpenseSource.INVOICE
        raw_extracted_text = extracted_data.raw_document_text
        prompt_data = {
            "vendor_name": extracted_data.vendor_name,
            "document_date": extracted_data.invoice_date,
            "total_amount": extracted_data.total_amount,
            "currency": "USD", # Assuming USD for simplicity
            "line_items": [
                {"description": item.description, "amount": item.amount} 
                for item in extracted_data.line_items
            ]
        }
    elif isinstance(extracted_data, ReceiptFields):
        source_type = ExpenseSource.RECEIPT
        raw_extracted_text = extracted_data.raw_document_text
        prompt_data = {
            "vendor_name": extracted_data.merchant_name,
            "document_date": None, # Receipts often lack explicit date field, use current or estimate later
            "total_amount": extracted_data.total_amount,
            "currency": "USD", # Assuming USD for simplicity
            "tax_amount": extracted_data.tax_amount,
            "line_items": [
                {"description": item.description, "amount": item.amount} 
                for item in extracted_data.items
            ]
        }
    else:
        raise ValueError("Unsupported extracted data type.")

    # Define the target schema for NormalizedExpense
    target_schema = NormalizedExpense.model_json_schema()

    messages = [
        {
            "role": "system",
            "content": (
                "You are an expert at normalizing expense data into a strict JSON schema. "
                "Match the provided input data to the output schema as closely as possible. "
                "If a field is not available in the input, omit it from the output or set to null/default if schema requires. "
                "Always respond with a JSON object matching the provided schema exactly." 
                f"The target schema is: {json.dumps(target_schema)}"
            )
        },
        {
            "role": "user",
            "content": f"Normalize the following extracted expense data into the specified JSON schema: {json.dumps(prompt_data)}"
        }
    ]

    response = client.chat.completions.create(
        model="gpt-4o", # Concrete model identifier
        messages=messages,
        response_format={"type": "json_object"},
        temperature=0.0
    )

    normalized_json_str = response.choices[0].message.content
    normalized_data = NormalizedExpense.model_validate_json(normalized_json_str)

    # Add source specific fields
    normalized_data.source = source_type
    normalized_data.raw_extracted_text = raw_extracted_text

    return normalized_data",
