import json
from document_models import NormalizedExpense, ValidationResult
from document_client import get_anthropic_client

def validate_expense_fields(expense: NormalizedExpense) -> ValidationResult:
    client = get_anthropic_client()

    validation_rules = [
        "'vendor_name' must not be empty.",
        "'document_date' must be a valid date format (YYYY-MM-DD or similar) if present.",
        "'total_amount' must be a positive number.",
        "Each 'line_item' must have a 'description' and a positive 'amount'."
    ]

    messages = [
        {
            "role": "user",
            "content": (
                f"I need to validate the following expense record against a set of rules.\n\n"
                f"Expense Record: {expense.model_dump_json(indent=2)}\n\n"
                f"Validation Rules:\n"
                + "\n".join([f"- {rule}" for rule in validation_rules]) + "\n\n"
                "Please respond with a JSON object containing a boolean 'is_valid' and a list of 'validation_messages'. "
                "If valid, 'validation_messages' should be empty. Otherwise, list all failed rules." 
            )
        }
    ]

    response = client.messages.create(
        model="claude-3-opus-20240229", # Concrete model identifier
        max_tokens=500,
        messages=messages
    )

    # Anthropic models don't have a direct JSON mode like OpenAI, 
    # so we'll instruct it to produce JSON and then parse it.
    response_text = response.content[0].text

    try:
        validation_output = json.loads(response_text)
        is_valid = validation_output.get("is_valid", False)
        messages = validation_output.get("validation_messages", [])
    except json.JSONDecodeError:
        is_valid = False
        messages = [f"Failed to parse validation response from LLM: {response_text}"]

    return ValidationResult(is_valid=is_valid, messages=messages)",
