  "invoice_summary.py": "import os
from typing import Union
import google.generativeai as genai

from document_models import InvoiceFields, NormalizedExpense, SummaryResult
from document_client import get_gemini_client

def summarize_invoice(invoice_data: Union[InvoiceFields, NormalizedExpense]) -> SummaryResult:
    get_gemini_client() # Initializes the genai library with API key

    model = genai.GenerativeModel('gemini-pro') # Concrete model identifier

    if isinstance(invoice_data, InvoiceFields):
        vendor = invoice_data.vendor_name
        date = invoice_data.invoice_date
        total = invoice_data.total_amount
        items_summary = ", ".join([f"{item.description} (${item.amount:.2f})" for item in invoice_data.line_items[:3]])
        if len(invoice_data.line_items) > 3:
            items_summary += "..."
        prompt = (
            f"Summarize the following invoice details concisely for an expense report: "
            f"Vendor: {vendor}, Date: {date}, Total: ${total:.2f}. "
            f"Line items include: {items_summary if items_summary else 'No specific items listed.'}."
        )
    elif isinstance(invoice_data, NormalizedExpense):
        vendor = invoice_data.vendor_name
        date = invoice_data.document_date.isoformat() if invoice_data.document_date else 'N/A'
        total = invoice_data.total_amount
        items_summary = ", ".join([f"{item.description} (${item.amount:.2f})" for item in invoice_data.line_items[:3]])
        if len(invoice_data.line_items) > 3:
            items_summary += "..."
        prompt = (
            f"Summarize the following normalized expense record concisely for an expense report: "
            f"Vendor: {vendor}, Date: {date}, Total: ${total:.2f} {invoice_data.currency}. "
            f"Line items include: {items_summary if items_summary else 'No specific items listed.'}."
            f"Additional notes: {invoice_data.notes if invoice_data.notes else 'None'}"
        )
    else:
        raise ValueError("Unsupported invoice data type for summarization.")

    try:
        response = model.generate_content(prompt)
        summary_text = response.text
    except Exception as e:
        summary_text = f"Failed to generate summary: {str(e)}"

    return SummaryResult(summary_text=summary_text)",
  "vendor_text_safety.py": "import os
from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions
from azure.core.exceptions import HttpResponseError

from document_models import SafetyResult
from document_client import get_azure_content_safety_client

def moderate_vendor_notes(text: str) -> SafetyResult:
    if not text:
        return SafetyResult(is_safe=True, analysis_results={"message": "No text provided for moderation."})

    client = get_azure_content_safety_client()

    try:
        request = AnalyzeTextOptions(text=text)
        response = client.analyze_text(request)

        harm_categories = [category.category for category in response.categories_analysis]
        max_severity = max([category.severity for category in response.categories_analysis]) if response.categories_analysis else 0

        # Define what constitutes "unsafe" for this context (e.g., any severity > 0)
        is_safe = max_severity == 0

        analysis_results = {
            "categories_analysis": [
                {"category": c.category, "severity": c.severity} 
                for c in response.categories_analysis
            ],
            "max_severity": max_severity,
            "detected_harm_categories": [hc.category for hc in response.categories_analysis if hc.severity > 0]
        }

        return SafetyResult(is_safe=is_safe, analysis_results=analysis_results)

    except HttpResponseError as e:
        return SafetyResult(is_safe=False, analysis_results={"error": str(e), "message": "Azure Content Safety API error."})
    except Exception as e:
        return SafetyResult(is_safe=False, analysis_results={"error": str(e), "message": "An unexpected error occurred during moderation."})
