from google.cloud import translate_v3 as translate

from document_models import TranslationResult
from document_client import get_google_translate_client

def translate_text(text: str, target_language_code: str = "en") -> TranslationResult:
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    location = os.getenv("GOOGLE_CLOUD_LOCATION", "global") # 'global' is default for NMT v3

    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")

    client = get_google_translate_client()

    parent = f"projects/{project_id}/locations/{location}"

    try:
        response = client.translate_text(
            parent=parent,
            contents=[text],
            target_language_code=target_language_code,
        )

        translated_text = ""
        if response.translations:
            translated_text = response.translations[0].translated_text

        return TranslationResult(
            original_text=text,
            translated_text=translated_text,
            target_language=target_language_code
        )

    except Exception as e:
        # In a real application, you might log this error or handle it more gracefully
        return TranslationResult(
            original_text=text,
            translated_text=f"Translation failed: {str(e)}",
            target_language=target_language_code
        )
