import uuid
from datetime import date
from pymongo import MongoClient
from pymongo.errors import PyMongoError

from document_models import NormalizedExpense, PersistenceResult
from document_client import get_mongodb_client

def persist_expense_record(expense: NormalizedExpense) -> PersistenceResult:
    client = get_mongodb_client()

    db_name = os.getenv("MONGODB_DATABASE", "expenses_db")
    collection_name = os.getenv("MONGODB_COLLECTION", "expense_records")

    db = client[db_name]
    collection = db[collection_name]

    # Convert Pydantic model to a dictionary for MongoDB insertion
    # Use model_dump for more control over serialization, e.g., handling dates
    expense_data = expense.model_dump(
        mode='json', # Ensures dates are ISO 8601 strings, compatible with MongoDB JSON storage
        exclude_none=True, # Do not include fields with None values
        by_alias=True
    )

    # Ensure expense_id is present, generate if not
    if 'expense_id' not in expense_data or not expense_data['expense_id']:
        expense_data['expense_id'] = str(uuid.uuid4())

    # MongoDB uses _id, so we can map expense_id to _id or keep both
    # For this example, let's keep expense_id and let Mongo generate _id if not provided by us
    # If you want to use expense_id as _id, do: expense_data['_id'] = expense_data['expense_id']

    try:
        result = collection.insert_one(expense_data)
        if result.acknowledged:
            # The _id of the inserted document, which might be different from expense_id if not explicitly set
            inserted_id = str(result.inserted_id)
            return PersistenceResult(
                record_id=expense_data['expense_id'], 
                acknowledged=True, 
                message=f"Expense record '{expense_data['expense_id']}' persisted successfully with MongoDB _id: {inserted_id}."
            )
        else:
            return PersistenceResult(
                record_id=expense_data['expense_id'], 
                acknowledged=False, 
                message="Failed to acknowledge record insertion."
            )
    except PyMongoError as e:
        return PersistenceResult(
            record_id=expense_data['expense_id'], 
            acknowledged=False, 
            message=f"Failed to persist expense record: {str(e)}"
        )
    except Exception as e:
        return PersistenceResult(
            record_id=expense_data['expense_id'], 
            acknowledged=False, 
            message=f"An unexpected error occurred: {str(e)}"
        )
